 return <><PageTitle eyebrow="Intercity operations" title="Waybill desk" description="Review intake, reconcile verified payment and move parcels through dispatch milestones." action={<Button variant="outline" icon="refresh" onClick={reload}>Refresh</Button>}/>{loading?<Loading/>:error?<Card><p className="text-sm text-rose-600">{error}</p></Card>:!data?.waybills?.length?<Empty icon="box" title="No waybill requests"/>:<div className="space-y-3">{data.waybills.map(w=><Card key={w.id} padding="p-4 sm:p-5"><div className="flex flex-col gap-4 xl:flex-row xl:items-center xl:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-bold text-ink">{w.waybill_number||w.reference}</p><Badge status={w.status}/></div><p className="mt-1 text-xs text-slate-500">{w.origin} → {w.destination_city} · {w.weight} kg · {money(w.fee)}</p><p className="mt-1 text-[10px] text-slate-400">{w.sender_name} · {w.sender_phone} → {w.recipient_name} · {w.recipient_phone}</p><p className="mt-1 text-[10px] text-slate-400">Payment: {w.payment_status}</p></div><div className="flex flex-wrap gap-2">{w.payment_status!=='successful'&&<Button size="sm" variant="soft" onClick={()=>reconcile(w)}>Reconcile payment</Button>}{(updates[w.status]||[]).map(s=><Button key={s} size="sm" variant={['delivered','dispatched'].includes(s)?'primary':'outline'} loading={busy===w.id} onClick={()=>change(w,s)}>{statusLabel(s)}</Button>)}{w.waybill_number&&<Button size="sm" variant="ghost" onClick={async()=>{try{const d=await api(`/ops/waybills/${w.id}/label`);window.print();showToast?.({title:'Waybill label ready',message:d.barcodeValue});}catch(e){showToast?.({type:'error',message:e.message});}}} icon="qr">Label</Button>}</div></div></Card>)}</div>}</>;
